import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    zip_path = DOWNLOAD_DIR / filename

    try:
        endpoint_legacy_compatible = url.startswith("http://localhost") or ".internal" in url
        verify_cert = False if endpoint_legacy_compatible else True

        response = requests.get(url, stream=True, timeout=15, verify=verify_cert)
        response.raise_for_status()

        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)

        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            extracted_files = zip_ref.namelist()

        return ("Success", extracted_files)

    except requests.RequestException as e:
        return (f"Error: Network-related exception: {e}", [])
    except (zipfile.BadZipFile, IOError, OSError) as e:
        return (f"Error: File-related exception: {e}", [])

